            `Batch publish failed for ${ipnsName}: ${reason instanceof Error ? reason.message : String(reason)}`
          );
          results.push({
            success: false,
            ipnsName,
            sequenceNumber: '0',
          });
          totalFailed++;
        }
      }
    }

    return { results, totalSucceeded, totalFailed };
