  1→import {
  2→  Injectable,
  3→  HttpException,
  4→  HttpStatus,
  5→  BadRequestException,
  6→  ConflictException,
  7→  Logger,
  8→  Inject,
  9→  forwardRef,
 10→} from '@nestjs/common';
 11→import { InjectRepository } from '@nestjs/typeorm';
 12→import { Repository } from 'typeorm';
 13→import { FolderIpns } from './entities/folder-ipns.entity';
 14→import {
 15→  PublishIpnsDto,
 16→  PublishIpnsEntryDto,
 17→  PublishIpnsResponseDto,
 18→  BatchPublishIpnsDto,
 19→  BatchPublishIpnsResponseDto,
 20→} from './dto';
 21→import { RepublishService } from '../republish/republish.service';
 22→import { DelegatedRoutingClient } from './delegated-routing.client';
 23→import { MetricsService } from '../metrics/metrics.service';
 24→import { parseIpnsRecord } from './ipns-record-parser';
 25→import { MetricsService } from '../metrics/metrics.service';
 26→
 27→@Injectable()
 28→export class IpnsService {
 29→  private readonly logger = new Logger(IpnsService.name);
 30→
 31→  constructor(
 32→    @InjectRepository(FolderIpns)
 33→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 34→    private readonly delegatedRouting: DelegatedRoutingClient,
 35→    @Inject(forwardRef(() => RepublishService))
 36→    private readonly republishService: RepublishService,
 37→    private readonly metricsService: MetricsService
 38→  ) {}
 39→
 40→  /**
 41→   * Publish a pre-signed IPNS record to the IPFS network via delegated routing
 42→   * and track the folder in the database for TEE republishing
 43→   */
 44→  async publishRecord(
 45→    userId: string,
 46→    dto: PublishIpnsDto | PublishIpnsEntryDto,
 47→    recordType: 'folder' | 'file' = 'folder'
 48→  ): Promise<PublishIpnsResponseDto> {
 49→    const endTimer = this.metricsService.ipfsIpnsDuration.startTimer({
 50→      operation: 'publish',
 51→      source: '',
 52→    });
 53→    let result = 'success';
 54→
 55→    try {
 56→      // Validate base64 record
 57→      let recordBytes: Uint8Array;
 58→      try {
 59→        recordBytes = Uint8Array.from(atob(dto.record), (c) => c.charCodeAt(0));
 60→      } catch {
 61→        throw new BadRequestException('Invalid base64-encoded record');
 62→      }
 63→
 64→      // Save to DB first so resolve always has a fallback, even if delegated
 65→      // routing fails (e.g. rate-limited, network error, DHT propagation delay).
 66→      const folder = await this.upsertFolderIpns(
 67→        userId,
 68→        dto.ipnsName,
 69→        dto.metadataCid,
 70→        dto.encryptedIpnsPrivateKey,
 71→        dto.keyEpoch,
 72→        recordType,
 73→        dto.expectedSequenceNumber
 74→      );
 75→
 76→      // Publish to delegated routing API (best-effort — DB is the reliable source)
 77→      const publishStart = process.hrtime.bigint();
 78→      let publishOutcome = 'success';
 79→      try {
 80→        await this.delegatedRouting.publish(dto.ipnsName, recordBytes);
 81→      } catch (error) {
 82→        result = 'delegated_error';
 83→        publishOutcome = error instanceof Error && error.name === 'AbortError' ? 'timeout' : 'error';
 84→        this.logger.warn(
 85→          `Delegated routing publish failed for ${dto.ipnsName}, DB record saved: ${error instanceof Error ? error.message : String(error)}`
 86→        );
 87→      } finally {
 88→        const publishElapsed = Number(process.hrtime.bigint() - publishStart) / 1e9;
 89→        this.metricsService.ipnsPublishDuration.observe({ outcome: publishOutcome }, publishElapsed);
 90→      }
 91→
 92→      return {
 93→        success: true,
 94→        ipnsName: dto.ipnsName,
 95→        sequenceNumber: folder.sequenceNumber,
 96→      };
 97→    } catch (error) {
 98→      result = 'error';
 99→      throw error;
100→    } finally {
101→      endTimer({ result });
102→    }
103→  }
104→
105→  /**
106→   * Batch publish multiple IPNS records with concurrency-limited processing.
107→   * Supports partial success: individual record failures do not fail the batch.
108→   * Processes up to 10 records concurrently.
109→   */
110→  async publishBatch(
111→    userId: string,
112→    dto: BatchPublishIpnsDto
113→  ): Promise<BatchPublishIpnsResponseDto> {
114→    const results: PublishIpnsResponseDto[] = [];
115→    let totalSucceeded = 0;
116→    let totalFailed = 0;
117→
118→    const CONCURRENCY = 10;
119→
120→    // Process records in batches of CONCURRENCY, delegating to publishRecord
121→    for (let i = 0; i < dto.records.length; i += CONCURRENCY) {
122→      const batch = dto.records.slice(i, i + CONCURRENCY);
123→
124→      const settled = await Promise.allSettled(
125→        batch.map((entry) => this.publishRecord(userId, entry, entry.recordType ?? 'folder'))
126→      );
127→
128→      for (let j = 0; j < settled.length; j++) {
129→        const result = settled[j];
130→        if (result.status === 'fulfilled') {
131→          results.push(result.value);
132→          totalSucceeded++;
133→        } else {
134→          const reason = result.reason;
135→          // If any record (especially a folder record) has a conflict, fail the entire batch
136→          if (reason instanceof ConflictException) {
137→            throw reason;
138→          }
139→          const ipnsName = batch[j]?.ipnsName ?? 'unknown';
140→          this.logger.warn(
141→            `Batch publish failed for ${ipnsName}: ${reason instanceof Error ? reason.message : String(reason)}`
142→          );
143→          results.push({
144→            success: false,
145→            ipnsName,
146→            sequenceNumber: '0',
147→          });
148→          totalFailed++;
149→        }
150→      }
151→    }
152→
153→    return { results, totalSucceeded, totalFailed };
154→  }
155→
156→  /**
157→   * Create or update a folder/file IPNS entry.
158→   * Handles both folder metadata and per-file metadata IPNS records.
159→   */
160→  private async upsertFolderIpns(
161→    userId: string,
162→    ipnsName: string,
163→    metadataCid: string,
164→    encryptedIpnsPrivateKey?: string,
165→    keyEpoch?: number,
166→    recordType: 'folder' | 'file' = 'folder',
167→    expectedSequenceNumber?: string
168→  ): Promise<FolderIpns> {
169→    const existing = await this.getFolderIpns(userId, ipnsName);
170→
171→    // Conflict detection: when expectedSequenceNumber is provided, verify it matches
172→    if (existing && expectedSequenceNumber !== undefined) {
173→      const expected = BigInt(expectedSequenceNumber);
174→      const current = BigInt(existing.sequenceNumber);
175→      if (expected !== current) {
176→        throw new ConflictException({
177→          statusCode: 409,
178→          message: 'Sequence number mismatch: folder was modified by another device',
179→          currentSequenceNumber: existing.sequenceNumber,
180→          expectedSequenceNumber,
181→        });
182→      }
183→    }
184→
185→    if (existing) {
186→      // Update existing entry
187→      existing.latestCid = metadataCid;
188→      existing.sequenceNumber = (BigInt(existing.sequenceNumber) + 1n).toString();
189→      existing.recordType = recordType;
190→      existing.updatedAt = new Date();
191→
192→      // Only update encrypted key if provided (e.g., on key rotation)
193→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
194→        existing.encryptedIpnsPrivateKey = Buffer.from(encryptedIpnsPrivateKey, 'hex');
195→        existing.keyEpoch = keyEpoch;
196→      }
197→
198→      const saved = await this.folderIpnsRepository.save(existing);
199→
200→      // Auto-enroll for TEE republishing when encrypted key is provided
201→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
202→        this.republishService
203→          .enrollFolder(
204→            userId,
205→            ipnsName,
206→            Buffer.from(encryptedIpnsPrivateKey, 'hex'),
207→            keyEpoch,
208→            metadataCid,
209→            saved.sequenceNumber
210→          )
211→          .catch((err) =>
212→            this.logger.warn(
213→              `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
214→            )
215→          );
216→      }
217→
218→      return saved;
219→    }
220→
221→    // Create new entry — sequence starts at '1' to match the IPNS record
222→    // the client signed (clients compute newSeq = 0n + 1n = 1n for first publish).
223→    const folder = this.folderIpnsRepository.create({
224→      userId,
225→      ipnsName,
226→      latestCid: metadataCid,
227→      sequenceNumber: '1',
228→      encryptedIpnsPrivateKey: encryptedIpnsPrivateKey
229→        ? Buffer.from(encryptedIpnsPrivateKey, 'hex')
230→        : null,
231→      keyEpoch: keyEpoch ?? null,
232→      isRoot: false, // Root folder is tracked in Vault entity
233→      recordType,
234→    });
235→
236→    const saved = await this.folderIpnsRepository.save(folder);
237→
238→    // Auto-enroll for TEE republishing when encrypted key is provided
239→    if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
240→      this.republishService
241→        .enrollFolder(
242→          userId,
243→          ipnsName,
244→          Buffer.from(encryptedIpnsPrivateKey, 'hex'),
245→          keyEpoch,
246→          metadataCid,
247→          saved.sequenceNumber
248→        )
249→        .catch((err) =>
250→          this.logger.warn(
251→            `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
252→          )
253→        );
254→    }
255→
256→    return saved;
257→  }
258→
259→  /**
260→   * Get a folder IPNS entry by user and IPNS name
261→   */
262→  async getFolderIpns(userId: string, ipnsName: string): Promise<FolderIpns | null> {
263→    return this.folderIpnsRepository.findOne({
264→      where: { userId, ipnsName },
265→    });
266→  }
267→
268→  /**
269→   * Get all folder IPNS entries for a user (for TEE republishing)
270→   */
271→  async getAllFolderIpns(userId: string): Promise<FolderIpns[]> {
272→    return this.folderIpnsRepository.find({
273→      where: { userId },
274→      order: { createdAt: 'ASC' },
275→    });
276→  }
277→
278→  /**
279→   * Resolve an IPNS name to its current CID via delegated routing,
280→   * falling back to the DB-cached CID when delegated routing is unavailable
281→   * or when the record is not found in the DHT.
282→   * Returns null if the IPNS name is not found anywhere (404)
283→   */
284→  async resolveRecord(ipnsName: string): Promise<{
285→    cid: string;
286→    sequenceNumber: string;
287→    signatureV2?: string;
288→    data?: string;
289→    pubKey?: string;
290→  } | null> {
291→    const endTimer = this.metricsService.ipfsIpnsDuration.startTimer({
292→      operation: 'resolve',
293→    });
294→    let timerResult = 'success';
295→    let timerSource = 'network';
296→    const startTime = process.hrtime.bigint();
297→    let source = 'network';
298→    let resolveFound = true;
299→
300→    try {
301→      let result: {
302→        cid: string;
303→        sequenceNumber: string;
304→        signatureV2?: string;
305→        data?: string;
306→        pubKey?: string;
307→      } | null = null;
308→
309→      try {
310→        const recordBytes = await this.delegatedRouting.resolve(ipnsName);
311→        if (recordBytes) {
312→          result = this.parseIpnsRecordBytes(recordBytes);
313→          this.logger.debug(`IPNS name resolved successfully: ${ipnsName} -> ${result.cid}`);
314→        }
315→      } catch (error) {
316→        // Fall back to DB cache on BAD_GATEWAY (delegated routing failures)
317→        if (error instanceof HttpException && error.getStatus() === HttpStatus.BAD_GATEWAY) {
318→          this.logger.warn(`Delegated routing failed for ${ipnsName}, falling back to DB cache`);
319→          timerResult = 'error';
320→          source = 'db_cache';
321→        } else {
322→          timerResult = 'error';
323→          throw error;
324→        }
325→      }
326→
327→      // Always check DB cache — it's written synchronously during publish
328→      // and may be ahead of the network (delegated routing can serve stale records)
329→      const cached = await this.folderIpnsRepository.findOne({
330→        where: { ipnsName },
331→      });
332→
333→      if (result && cached?.latestCid) {
334→        // Both sources available — prefer the one with the higher sequence number
335→        const networkSeq = BigInt(result.sequenceNumber);
336→        const dbSeq = BigInt(cached.sequenceNumber);
337→        if (dbSeq > networkSeq) {
338→          this.logger.log(
339→            `DB cache has newer sequence (${dbSeq} > ${networkSeq}) for ${ipnsName}, using DB: ${cached.latestCid}`
340→          );
341→          timerSource = 'db';
342→          source = 'network_stale';
343→          return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
344→        }
345→        timerSource = 'network';
346→        return result;
347→      }
348→
349→      if (result) {
350→        timerSource = 'network';
351→        return result;
352→      }
353→
354→      // Delegated routing returned null (404) or threw BAD_GATEWAY — try DB cache
355→      if (cached?.latestCid) {
356→        this.logger.log(`Resolved ${ipnsName} from DB cache: ${cached.latestCid}`);
357→        timerSource = 'db';
358→        source = 'db_cache';
359→        return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
360→      }
361→
362→      resolveFound = false;
363→      return null;
364→    } catch (error) {
365→      timerResult = 'error';
366→      throw error;
367→    } finally {
368→      endTimer({ result: timerResult, source: timerSource });
369→      if (resolveFound) {
370→        const elapsed = Number(process.hrtime.bigint() - startTime) / 1e9;
371→        this.metricsService.ipnsResolveDuration.observe({ source }, elapsed);
372→      }
373→    }
374→  }
375→
376→  /**
377→   * Parse an IPNS record to extract CID and sequence number
378→   * Uses inline protobuf decoder — no external dependencies
379→   */
380→  private parseIpnsRecordBytes(recordBytes: Uint8Array): {
381→    cid: string;
382→    sequenceNumber: string;
383→    signatureV2?: string;
384→    data?: string;
385→    pubKey?: string;
386→  } {
387→    try {
388→      const record = parseIpnsRecord(recordBytes);
389→
390→      // Extract CID from the Value field (format: /ipfs/<cid>)
391→      const valuePath = record.value;
392→      const cidMatch = valuePath.match(/\/ipfs\/([a-zA-Z0-9]+)/);
393→      if (!cidMatch) {
394→        this.logger.error('Failed to extract CID from IPNS record value');
395→        throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
396→      }
397→
398→      const cid = cidMatch[1];
399→      const sequenceNumber = String(record.sequence ?? 0n);
400→
401→      // Base64-encode signature fields if present
402→      const signatureV2 = record.signatureV2
403→        ? Buffer.from(record.signatureV2).toString('base64')
404→        : undefined;
405→      const data = record.data ? Buffer.from(record.data).toString('base64') : undefined;
406→      const pubKey = record.pubKey ? Buffer.from(record.pubKey).toString('base64') : undefined;
407→
408→      this.logger.debug(`Parsed IPNS record: cid=${cid}, sequenceNumber=${sequenceNumber}`);
409→      return { cid, sequenceNumber, signatureV2, data, pubKey };
410→    } catch (error) {
411→      if (error instanceof HttpException) {
412→        throw error;
413→      }
414→      this.logger.error(`Failed to parse IPNS record: ${error}`);
415→      throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
416→    }
417→  }
418→}
